45	/// When you call this, you can pass additional arguments to pass custom
46	/// arguments to flutter analyze. For example, you might want to call this
47	/// script with the parameter --dart-sdk to use custom dart sdk.
48	///
49	/// For example:
50	/// bin/cache/dart-sdk/bin/dart dev/bots/analyze.dart --dart-sdk=/tmp/dart-sdk
51	Future<void> main(List<String> arguments) async {
52	  try {
53	    await run(arguments);
54	  } on ExitException catch (error) {
55	    error.apply();
56	  }
57	  print('${bold}DONE: Analysis successful.$reset');
