127	Future<void> verifyNoMissingLicense(String workingDirectory) async {
128	  final List<String> errors = <String>[];
129	  for (FileSystemEntity entity in Directory(path.join(workingDirectory, 'packages'))
130	      .listSync(recursive: true)
131	      .where((FileSystemEntity entity) => entity is File && path.extension(entity.path) == '.dart')) {
132	    final File file = entity;
133	    bool hasLicense = false;
134	    final List<String> lines = file.readAsLinesSync();
135	    if (lines.isNotEmpty)
136	      hasLicense = lines.first.startsWith(RegExp(r'// Copyright \d{4}'));
137	    if (!hasLicense)
138	      errors.add(file.path);
139	  }
140	  // Fail if any errors
141	  if (errors.isNotEmpty) {
142	    print('$redLine');
143	    final String s = errors.length == 1 ? '' : 's';
144	    print('${bold}License headers cannot be found at the beginning of the following file$s.$reset\n');
145	    print(errors.join('\n'));
146	    print('$redLine\n');
147	    exit(1);
148	  }
149	}
