162	    .listSync(recursive: true)
163	    .where((FileSystemEntity entity) => entity is File && path.extension(entity.path) == '.dart')) {
164	    final File file = entity;
165	    for (String line in file.readAsLinesSync()) {
166	      final Match match = _testImportPattern.firstMatch(line);
167	      if (match != null && !_exemptTestImports.contains(match.group(2)))
168	        errors.add(file.path);
169	    }
170	  }
171	  // Fail if any errors
172	  if (errors.isNotEmpty) {
173	    print('$redLine');
174	    final String s = errors.length == 1 ? '' : 's';
175	    print('${bold}The following file$s import a test directly. Test utilities should be in their own file.$reset\n');
176	    print(errors.join('\n'));
177	    print('$redLine\n');
178	    exit(1);
179	  }
180	}
